            </div>

            <button onClick={() => setView('store')} className="hover:text-gulf-orange transition-colors">
              Catálogo
            </button>

            <button onClick={() => cart.length > 0 && setView('checkout')} className="relative hover:text-gulf-orange transition-colors">
