            </div>
            <form onSubmit={handleLogin} className="p-8 space-y-6">
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2">Punto de Venta</label>
                <div className="relative">
                   <User className="absolute left-3 top-3 text-gray-400" size={20}/>
                   <select 
                    required
                    className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-gulf-orange focus:border-transparent outline-none bg-white appearance-none"
                    value={loginPos}
                    onChange={(e) => setLoginPos(e.target.value)}
                   >
                     <option value="">Seleccione su POS...</option>
                     {clientsList.map(c => (
                       <option key={c.id} value={c.pointOfSale}>{c.pointOfSale}</option>
                     ))}
                   </select>
                </div>
              </div>
              <div>
