           <button onClick={() => setView('store')} className="bg-gulf-orange text-white px-8 py-3 rounded-full font-bold hover:bg-orange-600 transition-colors">
             Volver a la Tienda
           </button>
        </div>
      </div>
    );
  }

  return <div>Loading...</div>;
};

