type ViewState = 'login' | 'store' | 'checkout' | 'success' | 'admin';

interface RewardCardProps {
  reward: Reward;
  currentUser: Client;
  currentPoints: number;
  onAddToCart: (reward: Reward, qty: number) => void;
}

const CelebrationEffect = () => {
  // Generate random particles for confetti
  const particles = Array.from({ length: 24 }).map((_, i) => {
    const angle = Math.random() * 360;
    const velocity = 40 + Math.random() * 60; // Distance to travel
    const tx = Math.cos((angle * Math.PI) / 180) * velocity;
    const ty = Math.sin((angle * Math.PI) / 180) * velocity;

    // World Cup / Gulf Colors mix
    const colors = ['bg-[#F58025]', 'bg-[#002664]', 'bg-[#00A3E0]', 'bg-yellow-400', 'bg-red-500', 'bg-white'];
    const color = colors[Math.floor(Math.random() * colors.length)];
    const shape = Math.random() > 0.5 ? 'rounded-full' : 'rounded-sm';

    return { id: i, tx, ty, color, shape };
  });

  return (
    <>
      <style>
        {`
          @keyframes confetti-explode {
            0% { transform: translate(-50%, -50%) scale(0); opacity: 1; }
            60% { opacity: 1; }
            100% { transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(0.5) rotate(180deg); opacity: 0; }
          }
        `}
      </style>
      <div className="absolute inset-0 pointer-events-none overflow-hidden">
        {particles.map((p) => (
          <div
            key={p.id}
            className={`absolute top-1/2 left-1/2 w-2.5 h-2.5 ${p.color} ${p.shape} shadow-sm`}
            style={{
              '--tx': `${p.tx}px`,
              '--ty': `${p.ty}px`,
              animation: `confetti-explode ${0.6 + Math.random() * 0.4}s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards`,
            } as React.CSSProperties}
          />
        ))}
      </div>
    </>
  );
};

// Extracted Component to avoid "useState inside loop" error
const RewardCard: React.FC<RewardCardProps> = ({ 
  reward, 
  currentUser, 
  currentPoints, 
  onAddToCart 
}) => {
  const [qty, setQty] = useState(1);
  const [showSuccess, setShowSuccess] = useState(false);
  const price = currentUser.type === 'Pareto' ? reward.pointsPareto : reward.pointsNormal;
  const canAfford = currentPoints >= price;

  const handleClick = () => {
    onAddToCart(reward, qty);
    setShowSuccess(true);
    setTimeout(() => setShowSuccess(false), 2000);
  };

  return (
    <div className="bg-white rounded-xl shadow-md overflow-hidden hover:shadow-2xl transition-all duration-300 border border-gray-100 flex flex-col transform hover:-translate-y-2 group relative">
      <div className="h-48 overflow-hidden relative">
        <img 
            src={reward.imageUrl} 
            alt={reward.name} 
            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" 
        />
        {!canAfford && (
          <div className="absolute inset-0 bg-black/60 flex items-center justify-center backdrop-blur-[2px]">
            <span className="text-white font-bold border border-white px-3 py-1 rounded transform -rotate-12 tracking-wider shadow-lg">Insuficiente</span>
          </div>
        )}
        {showSuccess && (
             <div className="absolute inset-0 bg-gulf-blue/95 flex flex-col items-center justify-center z-20 animate-in fade-in duration-200">
                <CelebrationEffect />
                <div className="relative z-10 flex flex-col items-center animate-bounce">
                  <CheckCircle className="text-gulf-orange w-16 h-16 mb-2 drop-shadow-[0_2px_4px_rgba(0,0,0,0.3)] stroke-[3]" />
                  <span className="text-white font-bold text-3xl font-sports tracking-wide drop-shadow-md">¡GOLAZO!</span>
                  <span className="text-gulf-lightblue font-medium text-xs tracking-[0.2em] uppercase mt-1">Agregado al carrito</span>
                </div>
             </div>
        )}
      </div>
      <div className="p-6 flex-grow flex flex-col">
        <h4 className="text-xl font-bold text-gray-800 mb-2 leading-tight group-hover:text-gulf-blue transition-colors duration-300">{reward.name}</h4>
        <p className="text-gray-500 text-sm mb-4 flex-grow">{reward.description}</p>

        <div className="flex justify-between items-end mt-4">
          <div>
            <p className="text-xs text-gray-400 uppercase tracking-widest font-bold">Costo</p>
            <p className={`text-3xl font-sports ${canAfford ? 'text-gulf-blue' : 'text-red-400'}`}>
              {price.toLocaleString()} pts
            </p>
          </div>

          <div className="flex flex-col items-end gap-2">
             <div className="flex items-center border rounded-lg overflow-hidden bg-gray-50">
               <button onClick={() => setQty(Math.max(1, qty - 1))} className="px-3 py-1 hover:bg-gray-200 text-gray-600 transition-colors font-bold">-</button>
               <span className="px-2 w-8 text-center text-sm font-bold text-gray-800">{qty}</span>
               <button onClick={() => setQty(qty + 1)} className="px-3 py-1 hover:bg-gray-200 text-gray-600 transition-colors font-bold">+</button>
             </div>
             <button 
              onClick={handleClick}
              disabled={!canAfford}
              className={`px-4 py-2 rounded-lg font-bold text-sm shadow-sm transition-all transform active:scale-95 duration-200
                ${canAfford ? 'bg-gulf-orange text-white hover:bg-orange-600 hover:shadow-lg hover:-translate-y-0.5' : 'bg-gray-200 text-gray-400 cursor-not-allowed'}
              `}
             >
               CANJEAR
             </button>
          </div>
        </div>
      </div>
    </div>
  );
};

const App = () => {
  // Application State
  const [view, setView] = useState<ViewState>('login');
  const [currentUser, setCurrentUser] = useState<Client | null>(null);
  const [currentPoints, setCurrentPoints] = useState<number>(0);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [loading, setLoading] = useState(false);

  // Login Form State
  const [loginId, setLoginId] = useState('');
  const [loginPass, setLoginPass] = useState('');
  const [clientsList, setClientsList] = useState<Client[]>([]);

  // Order Form State
  const [orderDetails, setOrderDetails] = useState<OrderDetails>({
    address: '', receiver: '', city: '', phone: ''
  });

  // Load Data on Mount
  useEffect(() => {
    const db = getDatabase();
    setClientsList(db.clients);
  }, [view]);

  // Actions
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    // Validate credentials using ID (businessId) and Password
    const user = clientsList.find(c => c.businessId === loginId && c.password === loginPass);

    if (user) {
      setCurrentUser(user);
      setCurrentPoints(getPoints(user.pointOfSale));
      setView('store');
    } else {
      alert('ID o Contraseña incorrectos.');
    }
  };

  const addToCart = (reward: Reward, qty: number) => {
    if (qty <= 0) return;

    const price = currentUser?.type === 'Pareto' ? reward.pointsPareto : reward.pointsNormal;
    const existing = cart.find(c => c.id === reward.id);

    if (existing) {
      setCart(cart.map(c => c.id === reward.id ? { ...c, quantity: c.quantity + qty } : c));
    } else {
      setCart([...cart, { ...reward, quantity: qty, appliedPrice: price || 0 }]);
    }
    // Alert removed in favor of in-card animation
  };

  const removeFromCart = (id: string) => {
    setCart(cart.filter(c => c.id !== id));
  };

  const calculateTotal = () => {
    return cart.reduce((acc, item) => acc + (item.appliedPrice * item.quantity), 0);
  };

  const handleCheckout = (e: React.FormEvent) => {
    e.preventDefault();
    const total = calculateTotal();

    if (!currentUser) return;

    if (total > currentPoints) {
      alert(`Error: No tienes suficientes puntos. Necesitas ${total}, tienes ${currentPoints}.`);
      return;
    }

    setLoading(true);

    // Simulate Network Request
    setTimeout(() => {
      const success = deductPoints(currentUser.pointOfSale, total);
      if (success) {
        // Log "Email" to console
        console.log(`
          --- EMAIL ENVIADO ---
          Para: agallego@gulfcolombia.com, asismercadeo@gulfcolombia.com
          Asunto: Nuevo Canje de Premios - ${currentUser.pointOfSale}

          Detalles del Pedido:
          Punto de Venta: ${currentUser.pointOfSale}
          ID Cliente (NIT): ${currentUser.businessId}
          Tipo Cliente: ${currentUser.type}
          Items:
          ${cart.map(c => `- ${c.quantity}x ${c.name} (${c.appliedPrice} pts c/u)`).join('\n')}

          Total Puntos Redimidos: ${total}

          Datos de Envío:
          Recibe: ${orderDetails.receiver}
          Dirección: ${orderDetails.address}
          Ciudad: ${orderDetails.city}
          Teléfono: ${orderDetails.phone}
          ---------------------
        `);

        setCurrentPoints(prev => prev - total);
        setCart([]);
        setView('success');
      } else {
        alert('Error al procesar la transacción.');
      }
      setLoading(false);
    }, 1500);
