const CelebrationEffect = () => {
  // Generate random particles for confetti
  const particles = Array.from({ length: 24 }).map((_, i) => {
    const angle = Math.random() * 360;
    const velocity = 40 + Math.random() * 60; // Distance to travel
    const tx = Math.cos((angle * Math.PI) / 180) * velocity;
    const ty = Math.sin((angle * Math.PI) / 180) * velocity;

    // World Cup / Gulf Colors mix
    const colors = ['bg-[#F58025]', 'bg-[#002664]', 'bg-[#00A3E0]', 'bg-yellow-400', 'bg-red-500', 'bg-white'];
    const color = colors[Math.floor(Math.random() * colors.length)];
    const shape = Math.random() > 0.5 ? 'rounded-full' : 'rounded-sm';

    return { id: i, tx, ty, color, shape };
  });

  return (
    <>
      <style>
        {`
          @keyframes confetti-explode {
            0% { transform: translate(-50%, -50%) scale(0); opacity: 1; }
            60% { opacity: 1; }
            100% { transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(0.5) rotate(180deg); opacity: 0; }
          }
        `}
      </style>
      <div className="absolute inset-0 pointer-events-none overflow-hidden">
        {particles.map((p) => (
          <div
            key={p.id}
            className={`absolute top-1/2 left-1/2 w-2.5 h-2.5 ${p.color} ${p.shape} shadow-sm`}
            style={{
              '--tx': `${p.tx}px`,
              '--ty': `${p.ty}px`,
              animation: `confetti-explode ${0.6 + Math.random() * 0.4}s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards`,
            } as React.CSSProperties}
          />
        ))}
      </div>
    </>
  );
};

