                     <button onClick={() => setQty(qty + 1)} className="px-2 hover:bg-gray-200 text-gulf-blue font-bold text-xs h-full">+</button>
                  </div>
               </div>
            </div>

            {/* Gloss Overlay */}
            <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/20 to-transparent pointer-events-none z-20"></div>

          </div>
        </div>

        {/* The "Whistle" / Referee Card Action Button */}
        <div className="absolute -bottom-3 left-0 right-0 flex justify-center z-30">
           <button 
             onClick={handleClick}
             disabled={!canAfford}
             className={`
               whistle-btn
               group/btn relative flex items-center justify-center gap-2 px-6 py-2 
               rounded-lg shadow-lg border-b-4 transition-all duration-200
