                 ? 'bg-gulf-orange border-orange-700 text-white hover:bg-orange-500 hover:-translate-y-1' 
                 : 'bg-gray-300 border-gray-400 text-gray-500 cursor-not-allowed'}
             `}
           >
              <WhistleIcon className={`w-5 h-5 ${canAfford ? 'animate-pulse' : ''}`} />
