        const itemsText = cart.map(c => `- ${c.quantity}x ${c.name} (${c.appliedPrice} pts)`).join('\n');
        const body = `PEDIDO GULF 2026\nCliente: ${currentUser.pointOfSale}\nID: ${currentUser.businessId}\n\n${itemsText}\nTotal: ${total}`;
