                 onClick={handleClick}
                 disabled={!canAfford}
                 className={`
                   w-full relative overflow-hidden rounded-lg py-2.5 flex items-center justify-center gap-2 transition-all duration-300
                   ${canAfford 
                     ? 'bg-black text-white hover:bg-gray-900 shadow-lg hover:-translate-y-1 border-b-4 border-gray-700' 
                     : 'bg-gray-200 text-gray-400 cursor-not-allowed'}
