          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 relative z-10">
            {rewards.map(reward => (
              <RewardCard 
                key={reward.id} 
                reward={reward} 
                currentUser={currentUser} 
                currentPoints={currentPoints} 
