import React, { useState, useEffect } from 'react';
import { loadStripe } from '@stripe/stripe-js';
import { Elements } from '@stripe/react-stripe-js';
import { useLocation } from 'react-router-dom';
import { emailjs } from 'emailjs-com';

import CheckoutForm from './CheckoutForm';

const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLIC_KEY);

function App() {
  const [clientSecret, setClientSecret] = useState('');
  const [itemsInCart, setItemsInCart] = useState([]);
  const [emailError, setEmailError] = useState('');
  const location = useLocation();

  useEffect(() => {
    // Check to see if this is a redirect back from Checkout
    const query = new URLSearchParams(window.location.search);
    if (query.get('success')) {
      console.log('Order placed! You will receive an email confirmation.');
    }

    if (query.get('canceled')) {
      console.log('Order canceled -- continue to shop around and checkout when you are ready.');
    }
  }, [location]);

  useEffect(() => {
    // Fetch a new client secret from your backend
    fetch('/create-payment-intent', {
      method: 'POST',
      body: JSON.stringify({
        items: itemsInCart,
      }),
      headers: {
        'Content-Type': 'application/json',
      },
    })
      .then((res) => res.json())
      .then((data) => setClientSecret(data.clientSecret));
  }, [itemsInCart]);

  const appearance = {
    theme: 'stripe',
  };

  const options = {
    clientSecret,
    appearance,
  };

  const handleCheckout = async (items, stripe, elements) => {
    if (!stripe || !elements) {
      // Stripe.js has not loaded yet. Make sure to disable
      // form submission until Stripe.js has loaded.
      return;
    }

    const { error } = await stripe.confirmPayment({
      elements,
      redirect: 'if_required',
    });

    if (error) {
      // This point will only be reached if there is an immediate
      // error when confirming the payment. Show the error to your
      // customer (for example, payment details incomplete)
      console.log(error.message);
    } else {
      await sendEmail(items);
    }
  };


  const sendEmail = async (items) => {
    let emailSent = true;
    setEmailError(''); // Clear any previous error

    try {
      const templateParams = {
        to_email: 'recipient@example.com', // Replace with dynamic recipient
        message: JSON.stringify(items, null, 2),
      };

      const result = await emailjs.send(
        process.env.REACT_APP_EMAILJS_SERVICE_ID,
        process.env.REACT_APP_EMAILJS_TEMPLATE_ID,
        templateParams,
        process.env.REACT_APP_EMAILJS_PUBLIC_KEY
      );

      console.log('Email sent successfully!', result.text);

    } catch (error) {
        console.error('Email Failed:', JSON.stringify(error));
        emailSent = false;

        if (error && typeof error === 'object' && error.text) {
             emailError = error.text;
        } else if (error && error.message) {
             emailError = error.message;
        } else {
             emailError = 'No se pudo conectar con el servidor de correos.';
        }
    }
  };


  return (
    <div className="App">
      {clientSecret && (
        <Elements options={options} stripe={stripePromise}>
          <CheckoutForm handleCheckout={handleCheckout} setItemsInCart={setItemsInCart} itemsInCart={itemsInCart} emailError={emailError} />
        </Elements>
      )}
    </div>
  );
}

export default App

