         <div className="w-px h-12 bg-white/20"></div>
         <img src="https://i.postimg.cc/25m8ccQr/Prolub-LOGO.png" alt="Prolub" className="h-12 object-contain" />
      </div>

      <style>{`
        @keyframes run-progress {
          0% { width: 0%; }
          100% { width: 100%; }
        }
