                        <img 
                            src={images[currentImageIdx]} 
                            alt={reward.name} 
                            className={`max-w-full max-h-full object-contain transition-transform duration-500 origin-center ${isZoomed ? 'scale-150' : 'scale-100'}`} 
                        />
