                            <button 
                                key={idx}
                                onClick={() => setCurrentImageIdx(idx)}
                                className={`w-16 h-16 rounded-lg border-2 overflow-hidden flex-shrink-0 transition-all ${currentImageIdx === idx ? 'border-gulf-orange ring-2 ring-gulf-orange/30 scale-105' : 'border-gray-300 hover:border-gray-400'}`}
