const App = () => {
    const [user, setUser] = useState<Client | 'admin' | null>(null);
    const [rewards, setRewards] = useState<Reward[]>([]);
    const [points, setPoints] = useState(0);
    const [cart, setCart] = useState<CartItem[]>([]);
    const [isCartOpen, setIsCartOpen] = useState(false);
    const [selectedReward, setSelectedReward] = useState<Reward | null>(null);

    useEffect(() => {
        setRewards(getRewards());
    }, []);

    const handleLogin = (u: string, p: string) => {
        if (u === 'admin' && p === 'admin') {
            setUser('admin');
            return;
        }

        const clients = getClients();
        const found = clients.find(c => c.businessId === u && c.password === p);
        if (found) {
            setUser(found);
            setPoints(getPoints(found.pointOfSale));
        } else {
            alert('Credenciales incorrectas');
        }
    };

    const handleLogout = () => {
        setUser(null);
        setCart([]);
        setPoints(0);
    };

    const addToCart = (reward: Reward, qty: number) => {
        if (!user || user === 'admin') return;
        const price = user.type === 'Pareto' ? reward.pointsPareto : reward.pointsNormal;

        setCart(prev => {
            const existing = prev.find(item => item.id === reward.id);
            if (existing) {
                return prev.map(item => item.id === reward.id ? { ...item, quantity: item.quantity + qty } : item);
            }
            return [...prev, { ...reward, quantity: qty, appliedPrice: price }];
        });
    };

    const removeFromCart = (id: string) => {
        setCart(prev => prev.filter(item => item.id !== id));
    };

    const cartTotal = cart.reduce((acc, item) => acc + (item.appliedPrice * item.quantity), 0);

    const submitOrder = () => {
        if (!user || user === 'admin') return;
        if (cartTotal > points) {
            alert('No tienes suficientes puntos.');
            return;
        }
        if (deductPoints(user.pointOfSale, cartTotal)) {
            setPoints(prev => prev - cartTotal);
            setCart([]);
            alert('¡Canje exitoso! Tus premios llegarán pronto.');
            setIsCartOpen(false);
        } else {
            alert('Error al procesar el canje.');
        }
    };

    if (!user) return <LoginScreen onLogin={handleLogin} />;

    if (user === 'admin') return <AdminPanel onLogout={handleLogout} />;

    return (
        <div className="min-h-screen bg-gray-50 pb-20">
            {/* Navbar */}
            <header className="bg-white shadow-sm sticky top-0 z-50">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
                    <div className="flex items-center gap-2">
                        <div className="bg-gulf-blue text-white p-2 rounded-lg font-sports text-xl">GP</div>
                        <span className="font-sports text-2xl text-gulf-blue hidden sm:block">PROLUB</span>
                    </div>

                    <div className="flex items-center gap-6">
                        <div className="flex flex-col items-end mr-2">
                            <span className="text-xs text-gray-400 uppercase font-bold tracking-wider">Tus Puntos</span>
                            <span className="text-2xl font-sports text-gulf-orange">{points.toLocaleString()}</span>
                        </div>

                        <button 
                            onClick={() => setIsCartOpen(true)}
                            className="relative p-2 text-gray-600 hover:text-gulf-blue transition-colors"
                        >
                            <ShoppingCart size={24} />
                            {cart.length > 0 && (
                                <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] font-bold w-5 h-5 flex items-center justify-center rounded-full border-2 border-white">
                                    {cart.reduce((a, b) => a + b.quantity, 0)}
                                </span>
                            )}
                        </button>

                        <div className="h-8 w-px bg-gray-200 mx-2"></div>

                        <div className="flex items-center gap-3">
                            <div className="text-right hidden md:block">
                                <p className="text-sm font-bold text-gray-700">{user.pointOfSale}</p>
                                <p className="text-xs text-gray-500">{user.type} User</p>
                            </div>
                            <div className="w-10 h-10 bg-gray-100 rounded-full flex items-center justify-center">
                                <User size={20} className="text-gray-500" />
                            </div>
                            <button onClick={handleLogout} className="text-red-400 hover:text-red-600 ml-2" title="Salir">
                                <LogOut size={20} />
                            </button>
                        </div>
                    </div>
                </div>
            </header>

            {/* Hero */}
            <div className="bg-gulf-blue text-white py-12 mb-10">
                <div className="max-w-7xl mx-auto px-4">
                    <h1 className="text-4xl md:text-5xl font-sports mb-4">CATÁLOGO DE PREMIOS</h1>
                    <p className="text-blue-200 text-lg max-w-2xl">Canjea tus puntos por premios exclusivos. Elige a tus jugadores y arma tu alineación ganadora.</p>
                </div>
            </div>

            {/* Grid */}
            <main className="max-w-7xl mx-auto px-4">
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
                    {rewards.map(reward => {
                        const price = user.type === 'Pareto' ? reward.pointsPareto : reward.pointsNormal;
                        return (
                            <div 
                                key={reward.id} 
                                className="bg-white rounded-2xl shadow-sm hover:shadow-xl transition-all duration-300 group overflow-hidden cursor-pointer border border-gray-100 flex flex-col"
                                onClick={() => setSelectedReward(reward)}
                            >
                                <div className="relative aspect-square overflow-hidden bg-gray-100">
                                    <img 
                                        src={reward.imageUrls[0]} 
                                        alt={reward.name} 
                                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                                    />
                                    {price > 400 && (
                                        <span className="absolute top-3 left-3 bg-white/90 backdrop-blur text-gulf-blue text-[10px] font-bold px-2 py-1 rounded-full flex items-center gap-1 shadow-sm">
                                            <Sparkles size={10} className="text-yellow-500" /> DESTACADO
                                        </span>
                                    )}
                                </div>
                                <div className="p-5 flex-1 flex flex-col">
                                    <h3 className="font-sports text-lg text-gray-800 leading-tight mb-2 group-hover:text-gulf-blue transition-colors">
                                        {reward.name}
                                    </h3>
                                    <div className="mt-auto pt-4 flex items-center justify-between border-t border-gray-50">
                                        <div className="flex flex-col">
                                            <span className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">Valor</span>
                                            <span className="font-bold text-xl text-gulf-orange">{price} pts</span>
                                        </div>
                                        <button className="bg-gray-100 hover:bg-gulf-blue hover:text-white p-2 rounded-lg transition-colors">
                                            <ShoppingCart size={18} />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </main>

            {/* Cart Sidebar */}
            {isCartOpen && (
                <div className="fixed inset-0 z-50 flex justify-end">
                    <div className="absolute inset-0 bg-black/30 backdrop-blur-sm" onClick={() => setIsCartOpen(false)}></div>
                    <div className="relative w-full max-w-md bg-white h-full shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">
                        <div className="p-6 border-b flex items-center justify-between bg-gray-50">
                            <h2 className="font-sports text-2xl text-gulf-blue">TU ALINEACIÓN</h2>
                            <button onClick={() => setIsCartOpen(false)} className="text-gray-400 hover:text-gray-600">
                                <X size={24} />
                            </button>
                        </div>

                        <div className="flex-1 overflow-y-auto p-6 space-y-4">
                            {cart.length === 0 ? (
                                <div className="h-full flex flex-col items-center justify-center text-gray-400 space-y-4">
                                    <ShoppingCart size={48} className="opacity-20" />
                                    <p>Tu alineación está vacía.</p>
                                    <button 
                                        onClick={() => setIsCartOpen(false)} 
                                        className="text-gulf-orange font-bold text-sm hover:underline"
                                    >
                                        IR A FICHAR JUGADORES
                                    </button>
                                </div>
                            ) : (
                                cart.map(item => (
                                    <div key={item.id} className="flex gap-4 bg-white p-3 rounded-xl border border-gray-100 shadow-sm">
                                        <img src={item.imageUrls[0]} alt="" className="w-20 h-20 rounded-lg object-cover bg-gray-100" />
                                        <div className="flex-1">
                                            <h4 className="font-bold text-sm text-gray-800 line-clamp-1">{item.name}</h4>
                                            <div className="flex items-center gap-2 mt-1">
                                                <span className="text-xs text-gray-500">Cant: {item.quantity}</span>
                                                <span className="text-xs text-gulf-orange font-bold">{item.appliedPrice * item.quantity} pts</span>
                                            </div>
                                        </div>
                                        <button 
                                            onClick={() => removeFromCart(item.id)}
                                            className="self-center p-2 text-gray-300 hover:text-red-500 transition-colors"
                                        >
                                            <Trash2 size={18} />
                                        </button>
                                    </div>
                                ))
                            )}
                        </div>

                        {cart.length > 0 && (
                            <div className="p-6 bg-gray-50 border-t">
                                <div className="flex justify-between items-center mb-4">
                                    <span className="text-gray-500 font-bold">TOTAL PUNTOS</span>
                                    <span className={`text-2xl font-sports ${cartTotal > points ? 'text-red-500' : 'text-gulf-blue'}`}>
                                        {cartTotal}
                                    </span>
                                </div>
                                {cartTotal > points && (
                                    <p className="text-red-500 text-xs text-center mb-3 font-bold">
                                        Puntos insuficientes ({points - cartTotal})
                                    </p>
                                )}
                                <button 
                                    onClick={submitOrder}
                                    disabled={cartTotal > points}
                                    className={`w-full py-4 rounded-xl font-sports text-xl tracking-wide shadow-lg transition-all 
                                        ${cartTotal <= points 
                                            ? 'bg-gulf-blue text-white hover:bg-blue-900' 
                                            : 'bg-gray-200 text-gray-400 cursor-not-allowed'}
                                    `}
                                >
                                    CONFIRMAR CANJE
                                </button>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* Product Modal */}
            <ProductModal 
                isOpen={!!selectedReward}
                onClose={() => setSelectedReward(null)}
                reward={selectedReward}
                currentUser={user}
                currentPoints={points}
                onAddToCart={addToCart}
            />
        </div>
    );
};

