// Main App Component
export default function App() {
  const [currentUser, setCurrentUser] = useState<Client | null>(null);
  const [currentPoints, setCurrentPoints] = useState(0);
  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPass, setAdminPass] = useState('');

  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);

  const rewards = getRewards();

  // Load points when user changes
  useEffect(() => {
    if (currentUser) {
        const pts = getPoints(currentUser.pointOfSale);
        setCurrentPoints(pts);
    }
  }, [currentUser]);

  // Cart Helpers
  const addToCart = (reward: Reward) => {
    if (!currentUser) return;
    const price = currentUser.type === 'Pareto' ? reward.pointsPareto : reward.pointsNormal;

    setCart(prev => {
        const existing = prev.find(i => i.id === reward.id);
        if (existing) {
            return prev.map(i => i.id === reward.id ? { ...i, quantity: i.quantity + 1 } : i);
        }
        return [...prev, { ...reward, quantity: 1, appliedPrice: price }];
    });
    setIsCartOpen(true);
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(i => i.id !== id));
  };

  const cartTotal = cart.reduce((sum, item) => sum + (item.appliedPrice * item.quantity), 0);

  const handleCheckout = () => {
    if (!currentUser) return;

    if (currentPoints >= cartTotal) {
        if (confirm(`¿Confirmas el canje de estos premios por ${cartTotal} puntos?`)) {
            const success = deductPoints(currentUser.pointOfSale, cartTotal);
            if (success) {
                alert('¡Canje exitoso! Disfruta tus premios.');
                setCart([]);
                setIsCartOpen(false);
                setCurrentPoints(prev => prev - cartTotal);
            } else {
                alert('Error al procesar el canje.');
            }
        }
    } else {
        alert('No tienes suficientes puntos para este canje.');
    }
  };

  // Render Logic

  if (isAdmin) {
    return <AdminPanel onLogout={() => { setIsAdmin(false); setShowAdminLogin(false); }} />;
  }

  if (showAdminLogin) {
    return (
        <div className="min-h-screen flex items-center justify-center bg-gray-900">
            <div className="bg-white p-8 rounded shadow-lg max-w-sm w-full">
                <h2 className="text-xl font-bold mb-4">Acceso Administrativo</h2>
                <input 
                    type="password" 
                    value={adminPass} 
                    onChange={e => setAdminPass(e.target.value)} 
                    placeholder="Contraseña Admin"
                    className="border p-2 w-full mb-4 rounded"
                />
                <div className="flex gap-2 justify-end">
                    <button onClick={() => setShowAdminLogin(false)} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">Cancelar</button>
                    <button 
                        onClick={() => {
                            if (adminPass === 'gulf2025') setIsAdmin(true);
                            else alert('Contraseña incorrecta');
                        }} 
                        className="px-4 py-2 bg-gulf-blue text-white rounded hover:bg-blue-800"
                    >
                        Ingresar
                    </button>
                </div>
            </div>
        </div>
    )
  }

  if (!currentUser) {
    return <Login onLogin={setCurrentUser} onAdmin={() => setShowAdminLogin(true)} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 pb-20 font-sans">
      <StoreBanner currentUser={currentUser} currentPoints={currentPoints} />

      <div className="container mx-auto px-6 py-8">
        <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
            <h3 className="text-3xl font-black text-gulf-blue italic uppercase tracking-tighter">Catálogo de Premios</h3>

            <div className="flex gap-4">
                <button 
                    onClick={() => setIsCartOpen(true)}
                    className="relative bg-white border border-gulf-blue text-gulf-blue px-6 py-2 rounded-full font-bold shadow hover:bg-blue-50 transition flex items-center gap-2"
                >
                    <ShoppingCart size={20} />
                    Mi Carrito
                    {cart.length > 0 && (
                        <span className="absolute -top-2 -right-2 bg-gulf-orange text-white text-xs w-6 h-6 flex items-center justify-center rounded-full border-2 border-white">
                            {cart.reduce((a,c) => a + c.quantity, 0)}
                        </span>
                    )}
                </button>
                <button 
                    onClick={() => setCurrentUser(null)}
                    className="text-gray-500 hover:text-red-500 flex items-center gap-1 font-medium"
                >
                    <LogOut size={20} /> Salir
                </button>
            </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {rewards.map(reward => {
                const price = currentUser.type === 'Pareto' ? reward.pointsPareto : reward.pointsNormal;
                const canAfford = currentPoints >= price;

                return (
                    <div key={reward.id} className="bg-white rounded-xl shadow-lg overflow-hidden border border-gray-100 group hover:shadow-2xl transition-all duration-300 flex flex-col">
                        <div className="h-64 overflow-hidden relative bg-gray-100">
                             <img 
                                src={reward.imageUrls[0]} 
                                alt={reward.name} 
                                className="w-full h-full object-contain p-4 group-hover:scale-110 transition-transform duration-500 mix-blend-multiply" 
                             />
                             {!canAfford && (
                                 <div className="absolute inset-0 bg-white/50 backdrop-blur-[2px] flex items-center justify-center">
                                     <span className="bg-gray-800 text-white px-3 py-1 rounded text-sm font-bold flex items-center gap-1">
                                         <AlertCircle size={14} /> Faltan {price - currentPoints} pts
                                     </span>
                                 </div>
                             )}
                        </div>
                        <div className="p-6 flex-1 flex flex-col justify-between">
                            <div>
                                <h4 className="text-xl font-bold text-gray-900 mb-2 leading-tight">{reward.name}</h4>
                                <p className="text-gray-500 text-sm mb-4 line-clamp-3">{reward.description}</p>
                            </div>

                            <div className="flex items-end justify-between mt-4">
                                <div>
                                    <p className="text-xs text-gray-400 uppercase font-bold">Valor para ti</p>
                                    <p className={`text-3xl font-black ${canAfford ? 'text-gulf-blue' : 'text-gray-400'}`}>
                                        {price} <span className="text-sm font-normal text-gray-500">Pts</span>
                                    </p>
                                </div>
                                <button 
                                    onClick={() => addToCart(reward)}
                                    disabled={!canAfford}
                                    className={`px-4 py-2 rounded-lg font-bold flex items-center gap-2 transition-colors ${
                                        canAfford 
                                        ? 'bg-gulf-orange hover:bg-orange-600 text-white shadow-lg shadow-orange-500/30' 
                                        : 'bg-gray-200 text-gray-400 cursor-not-allowed'
                                    }`}
                                >
                                    <ShoppingCart size={18} /> {canAfford ? 'Agregar' : 'Insuficiente'}
                                </button>
                            </div>
                        </div>
                    </div>
                );
            })}
        </div>
      </div>

      {isCartOpen && (
          <CartModal 
            cart={cart} 
            totalPoints={cartTotal} 
            onClose={() => setIsCartOpen(false)} 
            onRemove={removeFromCart}
            onCheckout={handleCheckout}
          />
      )}
    </div>
  );
}

