                </div>

                {/* Right: Info */}
                <div className="w-full md:w-1/2 p-8 md:p-12 flex flex-col bg-white">
                    <div className="flex items-center gap-2 mb-2">
                        <span className="bg-gulf-blue/10 text-gulf-blue px-2 py-1 rounded text-[10px] font-bold uppercase tracking-widest">
