        const response = await emailjs.send(SERVICE_ID, TEMPLATE_ID, templateParams, PUBLIC_KEY);
        console.log('EmailJS Response:', response);

        if (response.status === 200) {
           emailSent = true;
        } else {
           throw new Error(`Status ${response.status}: ${response.text}`);
        }

