        let errorMsg = 'Unknown error';
        if (error instanceof Error) errorMsg = error.message;
        else if (typeof error === 'object' && error?.text) errorMsg = error.text;
        else errorMsg = String(error);

        console.error('Email Test Failed:', errorMsg);
