import React, { useState, useEffect } from 'react';
import { ShoppingCart, LogOut, User, MapPin, Phone, Truck, CheckCircle, AlertCircle, Menu, X, ChevronRight, Star, ArrowRight } from 'lucide-react';
import emailjs from '@emailjs/browser';
import { Client, CartItem, OrderDetails, OrderLog, Reward } from './types';
import { getClients, getPoints, getRewards, deductPoints, addOrder } from './services/db';
import { sendOrderToGoogleSheet } from './services/googleSheets';
import { AdminPanel } from './components/AdminPanel';

// EmailJS Config (Shared)
const SERVICE_ID = 'service_hdlsj5r';
const TEMPLATE_ID = 'template_rrqgdym';
const PUBLIC_KEY = 'pfbP31YCRZ3dzBat5';

export default function App() {
  const [view, setView] = useState<'login' | 'catalog' | 'cart' | 'success' | 'admin'>('login');
  const [user, setUser] = useState<Client | null>(null);
  const [availablePoints, setAvailablePoints] = useState(0);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  // Login State
  const [loginId, setLoginId] = useState('');
  const [loginPass, setLoginPass] = useState('');
  const [loginError, setLoginError] = useState('');

  // Checkout State
  const [orderDetails, setOrderDetails] = useState<OrderDetails>({
    address: '',
    receiver: '',
    city: '',
    phone: ''
  });
  const [isProcessing, setIsProcessing] = useState(false);

  useEffect(() => {
    if (user) {
      setAvailablePoints(getPoints(user.pointOfSale));
    }
  }, [user, view]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const clients = getClients();
    // Verify credentials
    // Note: In a real app, use safer comparison. Here we match CSV data.
    const found = clients.find(c => (c.businessId === loginId || c.pointOfSale === loginId) && c.password === loginPass);

    if (found) {
      setUser(found);
      setAvailablePoints(getPoints(found.pointOfSale));
      setView('catalog');
      setLoginError('');
    } else {
      setLoginError('Credenciales inválidas. Verifique ID y contraseña.');
    }
  };

  const handleAdminAccess = () => {
    const pass = prompt("Ingrese contraseña de administrador:");
    if (pass === "admin123" || pass === "gulf2024") { // Simple protection
      setView('admin');
    } else {
      alert("Acceso denegado");
    }
  };

  const handleLogout = () => {
    setUser(null);
    setCart([]);
    setView('login');
    setLoginId('');
    setLoginPass('');
    setIsMenuOpen(false);
  };

  const addToCart = (reward: Reward) => {
    const price = user?.type === 'Pareto' ? reward.pointsPareto : reward.pointsNormal;

    setCart(prev => {
      const existing = prev.find(item => item.id === reward.id);
      if (existing) {
        return prev.map(item => item.id === reward.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...reward, quantity: 1, appliedPrice: price }];
    });
    alert('Producto agregado al carrito');
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const calculateTotal = () => {
    return cart.reduce((sum, item) => sum + (item.appliedPrice * item.quantity), 0);
  };

  const handleCheckout = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;

    const total = calculateTotal();

    if (total > availablePoints) {
      alert('No tienes suficientes puntos para realizar este canje.');
      return;
    }

    if (!orderDetails.address || !orderDetails.receiver || !orderDetails.city || !orderDetails.phone) {
        alert('Por favor complete todos los datos de envío.');
        return;
    }

    if (!confirm('¿Estás seguro de confirmar el canje? Los puntos serán descontados.')) {
        return;
    }

    setIsProcessing(true);

    try {
        // 1. Deduct points locally
        const success = deductPoints(user.pointOfSale, total);
        if (!success) throw new Error("Error al descontar puntos");

        // 2. Prepare log
        const now = new Date();
        const orderLog: OrderLog = {
            date: now.toISOString().split('T')[0],
            time: now.toLocaleTimeString(),
            client: user.pointOfSale,
            receiver: orderDetails.receiver,
            city: orderDetails.city,
            address: orderDetails.address,
            phone: orderDetails.phone,
            items: cart.map(i => `${i.quantity}x ${i.name} (${i.appliedPrice} pts)`).join('\n')
        };

        // 3. Save to Local DB
        addOrder(orderLog);

        // 4. Send to Google Sheets
        await sendOrderToGoogleSheet(orderLog);

        // 5. Send Email
        const emailParams = {
            to_email: "asismercadeo@gulfcolombia.com,agallego@gulfcolombia.com", // Admin emails
            to_name: "Administrador",
            from_name: "Sistema Gulf Rewards",
            from_email: "noreply@rewards.com",
            subject: `NUEVO CANJE - ${user.pointOfSale}`,
            Premio: orderLog.items,
            "Nombre del receptor": orderLog.receiver,
            Cantidad: cart.reduce((acc, i) => acc + i.quantity, 0),
            "Dirección": orderLog.address,
            Telefono: orderLog.phone,
            Ciudad: orderLog.city,
            "Puntos gastados": total,
            message: `Nuevo pedido generado por ${user.pointOfSale} (ID: ${user.businessId}).`,
            customer_name: user.pointOfSale,
            customer_id: user.businessId
        };

        await emailjs.send(SERVICE_ID, TEMPLATE_ID, emailParams, PUBLIC_KEY);

        // Success
        setCart([]);
        setOrderDetails({ address: '', receiver: '', city: '', phone: '' });
        setAvailablePoints(prev => prev - total);
        setView('success');

    } catch (err) {
        console.error(err);
        alert('Hubo un error procesando el pedido. Por favor intente nuevamente o contacte a soporte.');
    } finally {
        setIsProcessing(false);
    }
  };

  // --- RENDERING ---

  if (view === 'admin') {
      return <AdminPanel onLogout={() => setView('login')} />;
  }

  if (view === 'login') {
    return (
      <div className="min-h-screen bg-cover bg-center flex items-center justify-center p-4 relative" 
           style={{ backgroundImage: 'url("https://i.postimg.cc/k4whb2x1/Fondo-Login.webp")' }}>
        <div className="absolute inset-0 bg-black/50 backdrop-blur-sm"></div>

        <div className="relative z-10 w-full max-w-md">
            <div className="bg-white/10 backdrop-blur-md border border-white/20 p-8 rounded-2xl shadow-2xl">
                <div className="text-center mb-8">
                    <img src="https://i.postimg.cc/MKqdk40w/Logo-Gulf.png" alt="Gulf Logo" className="h-16 mx-auto mb-4" />
                    <h1 className="text-3xl font-bold text-white mb-2 font-sports italic">PROLUB REWARDS</h1>
                    <p className="text-gray-300">Ingresa para canjear tus premios</p>
                </div>

                <form onSubmit={handleLogin} className="space-y-6">
                    <div>
                        <label className="block text-white text-sm font-bold mb-2">ID Usuario</label>
                        <div className="relative">
                            <User className="absolute left-3 top-3 text-gray-400" size={20} />
                            <input 
                                type="text" 
                                value={loginId}
                                onChange={e => setLoginId(e.target.value)}
                                className="w-full pl-10 pr-4 py-2 bg-white/10 border border-white/20 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-gulf-orange transition-all"
                                placeholder="Ingrese su ID"
                            />
                        </div>
                    </div>

                    <div>
                        <label className="block text-white text-sm font-bold mb-2">Contraseña</label>
                        <input 
                            type="password" 
                            value={loginPass}
                            onChange={e => setLoginPass(e.target.value)}
                            className="w-full px-4 py-2 bg-white/10 border border-white/20 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-gulf-orange transition-all"
                            placeholder="••••••••"
                        />
                    </div>

                    {loginError && (
                        <div className="bg-red-500/20 border border-red-500/50 text-red-200 px-4 py-2 rounded-lg flex items-center text-sm">
                            <AlertCircle size={16} className="mr-2" />
                            {loginError}
                        </div>
                    )}

                    <button 
                        type="submit"
                        className="w-full bg-gradient-to-r from-orange-500 to-orange-600 hover:from-orange-600 hover:to-orange-700 text-white font-bold py-3 rounded-lg shadow-lg transform hover:scale-[1.02] transition-all"
                    >
                        INGRESAR
                    </button>
                </form>
            </div>

            <div className="mt-8 text-center">
                 <button onClick={handleAdminAccess} className="text-xs text-white/50 hover:text-white transition-colors uppercase tracking-widest font-bold">
                    Acceso Administrativo
                 </button>
            </div>
        </div>
      </div>
    );
  }

  // --- MAIN APP LAYOUT (Catalog, Cart, Success) ---
  const rewards = getRewards();
  const totalItems = cart.reduce((acc, item) => acc + item.quantity, 0);

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col">
        {/* Navbar */}
        <nav className="bg-white shadow-md sticky top-0 z-50">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div className="flex justify-between h-20 items-center">
                    <div className="flex items-center">
                        <img src="https://i.postimg.cc/MKqdk40w/Logo-Gulf.png" alt="Gulf" className="h-10 mr-4" />
                        <div className="hidden md:block">
                            <h2 className="text-lg font-bold text-gray-800 font-sports italic">PROLUB REWARDS</h2>
                            {user && <p className="text-xs text-gray-500">Bienvenido, {user.pointOfSale}</p>}
                        </div>
                    </div>

                    <div className="flex items-center space-x-4">
                        <div className="bg-orange-100 text-orange-800 px-4 py-2 rounded-full font-bold flex items-center shadow-inner">
                            <Star className="mr-2 fill-orange-500 text-orange-500" size={18} />
                            {availablePoints} Pts
                        </div>

                        <div className="relative cursor-pointer" onClick={() => setView('cart')}>
                            <ShoppingCart className={`text-gray-600 hover:text-orange-500 transition-colors ${view === 'cart' ? 'text-orange-600' : ''}`} size={28} />
                            {totalItems > 0 && (
                                <span className="absolute -top-2 -right-2 bg-red-500 text-white text-xs font-bold w-5 h-5 flex items-center justify-center rounded-full animate-bounce">
                                    {totalItems}
                                </span>
                            )}
                        </div>

                        <button onClick={handleLogout} className="text-gray-400 hover:text-red-500 transition-colors ml-4">
                            <LogOut size={24} />
                        </button>
                    </div>
                </div>
            </div>
        </nav>

        {/* Content */}
        <div className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">

