                            {cart.length === 0 ? (
                                <div className="text-center py-12">
                                    <ShoppingCart size={64} className="mx-auto text-gray-200 mb-4" />
                                    <p className="text-gray-500 text-lg">Tu carrito está vacío.</p>
                                    <button 
