                                            <div className="text-right min-w-[80px] mx-4">
                                                <p className="font-bold text-lg text-gray-800">{item.appliedPrice * item.quantity}</p>
                                                <p className="text-xs text-gray-400">Puntos</p>
                                            </div>

                                            <button onClick={() => removeFromCart(item.id)} className="text-red-400 hover:text-red-600 p-2">
