                                            <MapPin className="absolute top-3 left-3 text-gray-400" size={16} />
                                            <input 
                                                required
                                                type="text" 
                                                className="w-full pl-9 pr-3 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none"
