import React, { useState, useEffect } from 'react';
import { Client, Reward, CartItem, OrderDetails } from './types';
import { getClients, getRewards, getPoints, deductPoints, addOrder } from './services/db';
import { AdminPanel } from './components/AdminPanel';
import { ShoppingCart, LogOut, Trash2 } from 'lucide-react';
import emailjs from '@emailjs/browser';
import { sendOrderToGoogleSheet } from './services/googleSheets';

export default function App() {
  const [view, setView] = useState<'login' | 'shop' | 'cart' | 'admin'>('login');
  const [user, setUser] = useState<Client | null>(null);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const [rewards, setRewards] = useState<Reward[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [userPoints, setUserPoints] = useState(0);

  const [orderDetails, setOrderDetails] = useState<OrderDetails>({
    address: '', receiver: '', city: '', phone: ''
  });
  const [isProcessing, setIsProcessing] = useState(false);

  useEffect(() => {
    setRewards(getRewards());
  }, []);

  useEffect(() => {
    if (user) {
      setUserPoints(getPoints(user.pointOfSale));
    }
  }, [user, view, cart]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (username === 'admin' && password === 'gulf2025') {
      setView('admin');
      return;
    }

    const clients = getClients();
    const found = clients.find(c => 
      (c.pointOfSale.trim().toLowerCase() === username.trim().toLowerCase() || c.businessId === username) && 
      c.password === password
    );

    if (found) {
      setUser(found);
      setView('shop');
      setError('');
    } else {
      setError('Credenciales inválidas');
    }
  };

  const handleLogout = () => {
    setUser(null);
    setCart([]);
    setView('login');
    setUsername('');
    setPassword('');
  };

  const handleAdminAccess = () => {
    const pass = prompt("Ingrese clave de administrador:");
    if (pass === "gulf2025") {
        setView('admin');
    } else {
        alert("Acceso denegado");
    }
  };

  const addToCart = (reward: Reward) => {
    if (!user) return;
    const price = user.type === 'Pareto' ? reward.pointsPareto : reward.pointsNormal;
    setCart(prev => {
      const exists = prev.find(i => i.id === reward.id);
      if (exists) {
        return prev.map(i => i.id === reward.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { ...reward, quantity: 1, appliedPrice: price }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(i => i.id !== id));
  };

  const handleCheckout = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const total = cart.reduce((acc, item) => acc + (item.appliedPrice * item.quantity), 0);

    if (userPoints < total) {
      alert("Puntos insuficientes");
      return;
    }

    setIsProcessing(true);
    try {
      const success = deductPoints(user.pointOfSale, total);
      if (success) {
        const itemsList = cart.map(i => `${i.quantity}x ${i.name}`).join('\n');
        const orderLog = {
          date: new Date().toLocaleDateString(),
          time: new Date().toLocaleTimeString(),
          client: user.pointOfSale,
          receiver: orderDetails.receiver,
          city: orderDetails.city,
          address: orderDetails.address,
          phone: orderDetails.phone,
          items: itemsList
        };
        addOrder(orderLog);

        await sendOrderToGoogleSheet(orderLog);

        try {
            await emailjs.send('service_hdlsj5r', 'template_rrqgdym', {
                to_email: "asismercadeo@gulfcolombia.com,agallego@gulfcolombia.com",
                Premio: itemsList,
                "Nombre del receptor": orderDetails.receiver,
                Cantidad: cart.reduce((a,b)=>a+b.quantity,0),
                "Dirección": orderDetails.address,
                Telefono: orderDetails.phone,
                Ciudad: orderDetails.city,
                "Puntos gastados": total,
                customer_name: user.pointOfSale,
                message: "Nuevo pedido desde App Web"
            }, 'pfbP31YCRZ3dzBat5');
        } catch (e) {
            console.error("Email error", e);
        }

        alert("Pedido exitoso");
        setCart([]);
        setView('shop');
        setOrderDetails({ address: '', receiver: '', city: '', phone: '' });
    } else {
        alert("Error al procesar puntos");
      }
    } catch (err) {
      console.error(err);
      alert("Error en el sistema");
    } finally {
      setIsProcessing(false);
    }
  };

  if (view === 'admin') return <AdminPanel onLogout={() => setView('login')} />;

  if (view === 'login') {
    return (
      <div className="min-h-screen bg-gulf-blue flex flex-col items-center justify-center p-4">
        <div className="bg-white p-8 rounded-lg shadow-xl w-full max-w-md">
           <div className="flex justify-center mb-6">
             <img src="https://gulf.com.co/wp-content/uploads/2021/05/Logo-Gulf-Mesa-de-trabajo-1.png" alt="Gulf" className="h-12" />
           </div>
           <h2 className="text-2xl font-bold text-center text-gulf-blue mb-6 font-sports">REWARDS PROLUB</h2>
           <form onSubmit={handleLogin} className="space-y-4">
             <input className="w-full border p-2 rounded" placeholder="Punto de Venta" value={username} onChange={e => setUsername(e.target.value)} />
             <input className="w-full border p-2 rounded" type="password" placeholder="Contraseña" value={password} onChange={e => setPassword(e.target.value)} />
             {error && <p className="text-red-500 text-sm text-center">{error}</p>}
             <button type="submit" className="w-full bg-gulf-orange text-white py-2 rounded font-bold hover:bg-orange-600">INGRESAR</button>
           </form>
        </div>
        <div className="mt-6 text-center">
             <button onClick={handleAdminAccess} className="text-[10px] text-white/70 hover:text-white transition-colors uppercase tracking-widest font-bold bg-black/40 px-4 py-1 rounded-full border border-white/10 hover:bg-black/60">
                Mesa Técnica (Admin)
             </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <nav className="bg-white shadow sticky top-0 z-50 p-4">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center">
             <img src="https://gulf.com.co/wp-content/uploads/2021/05/Logo-Gulf-Mesa-de-trabajo-1.png" alt="Gulf" className="h-8 mr-2" />
             <span className="font-sports text-gulf-blue text-xl hidden sm:inline">REWARDS</span>
          </div>
          <div className="flex items-center space-x-4">
             <div className="text-right">
               <div className="text-xs font-bold text-gray-500">{user?.pointOfSale}</div>
               <div className="text-sm font-bold text-gulf-orange">{userPoints} pts</div>
             </div>
             <button onClick={() => setView('shop')} className={view === 'shop' ? 'text-gulf-blue font-bold' : 'text-gray-500'}>Premios</button>
             <button onClick={() => setView('cart')} className="relative text-gray-500 hover:text-gulf-blue">
               <ShoppingCart />
               {cart.length > 0 && <span className="absolute -top-2 -right-2 bg-red-500 text-white text-xs rounded-full w-5 h-5 flex items-center justify-center">{cart.reduce((a,b)=>a+b.quantity,0)}</span>}
             </button>
             <button onClick={handleLogout} className="text-red-500"><LogOut /></button>
          </div>
        </div>
      </nav>

      {view === 'shop' && (
        <div className="max-w-7xl mx-auto p-4">
           <h2 className="text-3xl font-sports text-gulf-blue mb-6 text-center">CATÁLOGO DE PREMIOS</h2>
           <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
             {rewards.map(r => {
               const price = user?.type === 'Pareto' ? r.pointsPareto : r.pointsNormal;
               const canBuy = userPoints >= price;
               return (
                 <div key={r.id} className="bg-white rounded shadow hover:shadow-lg transition flex flex-col">
                   <div className="h-48 bg-gray-200 relative">
                     <img src={r.imageUrls[0]} alt={r.name} className="w-full h-full object-cover" />
                     {user?.type === 'Pareto' && r.pointsPareto !== r.pointsNormal && <span className="absolute top-2 right-2 bg-yellow-400 text-xs px-2 py-1 rounded font-bold">Pareto</span>}
                   </div>
                   <div className="p-4 flex-1 flex flex-col">
                     <h3 className="font-bold text-lg">{r.name}</h3>
                     <p className="text-sm text-gray-500 flex-1">{r.description}</p>
                     <div className="mt-4 flex justify-between items-center">
                       <span className="text-xl font-bold text-gulf-orange">{price} pts</span>
                       <button onClick={() => addToCart(r)} disabled={!canBuy} className={`px-4 py-2 rounded text-sm font-bold text-white ${canBuy ? 'bg-gulf-blue hover:bg-blue-900' : 'bg-gray-300 cursor-not-allowed'}`}>
                         Canjear
                       </button>
                     </div>
                   </div>
                 </div>
               );
             })}
           </div>
        </div>
      )}

      {view === 'cart' && (
        <div className="max-w-4xl mx-auto p-4">
           <h2 className="text-2xl font-sports text-gulf-blue mb-6">Carrito de Compras</h2>
           {cart.length === 0 ? <p className="text-center text-gray-500">Tu carrito está vacío.</p> : (
             <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
               <div className="md:col-span-2 space-y-4">
                 {cart.map(item => (
                   <div key={item.id} className="bg-white p-4 rounded shadow flex justify-between items-center">
                      <div className="flex items-center gap-4">
                        <img src={item.imageUrls[0]} className="w-16 h-16 object-cover rounded" />
                        <div>
                          <div className="font-bold">{item.name}</div>
                          <div className="text-sm text-gray-500">{item.quantity} x {item.appliedPrice} pts</div>
                        </div>
                      </div>
                      <div className="flex items-center gap-4">
                        <div className="font-bold text-gulf-blue">{item.quantity * item.appliedPrice} pts</div>
                        <button onClick={() => removeFromCart(item.id)} className="text-red-500"><Trash2 size={18} /></button>
                      </div>
                   </div>
                 ))}
               </div>
               <div className="bg-white p-6 rounded shadow h-fit">
                 <h3 className="font-bold text-lg mb-4">Resumen</h3>
                 <div className="flex justify-between font-bold text-xl mb-4">
                   <span>Total:</span>
                   <span className="text-gulf-orange">{cart.reduce((a,b)=>a+(b.appliedPrice*b.quantity),0)} pts</span>
                 </div>
                 <form onSubmit={handleCheckout} className="space-y-3">
                   <input required placeholder="Nombre quien recibe" className="w-full border p-2 rounded text-sm" value={orderDetails.receiver} onChange={e=>setOrderDetails({...orderDetails, receiver:e.target.value})} />
                   <input required placeholder="Ciudad" className="w-full border p-2 rounded text-sm" value={orderDetails.city} onChange={e=>setOrderDetails({...orderDetails, city:e.target.value})} />
                   <input required placeholder="Dirección" className="w-full border p-2 rounded text-sm" value={orderDetails.address} onChange={e=>setOrderDetails({...orderDetails, address:e.target.value})} />
                   <input required placeholder="Teléfono" type="tel" className="w-full border p-2 rounded text-sm" value={orderDetails.phone} onChange={e=>setOrderDetails({...orderDetails, phone:e.target.value})} />
                   <button type="submit" disabled={isProcessing || userPoints < cart.reduce((a,b)=>a+(b.appliedPrice*b.quantity),0)} className="w-full bg-green-600 text-white font-bold py-3 rounded hover:bg-green-700 disabled:bg-gray-400">
                     {isProcessing ? 'Procesando...' : 'Confirmar Canje'}
                   </button>
                 </form>
               </div>
             </div>
           )}
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { ShoppingCart, User, LogOut, CheckCircle, Trophy, Flag, MapPin, Truck, Phone, Package, Menu, X, Settings, Hash, CircleDot, ClipboardList, Building2, Shirt, Medal, Sparkles, Gauge, Calendar, Activity, ChevronRight, Speaker, Users, Download, Share2, ZoomIn, ArrowLeft, ArrowRight, FileText } from 'lucide-react';
import { Client, Reward, OrderDetails, CartItem, OrderLog } from './types';
import { getDatabase, getPoints, deductPoints, addOrder } from './services/db';
